from pathlib import Path
import base64
import gzip

PACKAGE_REPLACE = ""

TEST_PACKAGE_REPLACE = ""

Path("firmware/components/storage/storage_package_replace.c").write_bytes(
    gzip.decompress(base64.b64decode(PACKAGE_REPLACE))
)
Path("tests/host/test_storage_package_replace.c").write_bytes(
    gzip.decompress(base64.b64decode(TEST_PACKAGE_REPLACE))
)

header = Path("firmware/components/storage/include/storage_package.h")
text = header.read_text()
needle = '''app_error_code_t storage_package_export_set(const app_uuid_t *set_id, bool include_progress,
                                             char **out_data, size_t *out_length);
'''
replacement = needle + '''app_error_code_t storage_package_replace_set(const app_uuid_t *target_set_id,
                                             uint32_t expected_revision, const char *data,
                                             size_t length, macro_set_t *out_set);
'''
if text.count(needle) != 1 or "storage_package_replace_set" in text:
    raise SystemExit("storage package public API insertion point changed")
header.write_text(text.replace(needle, replacement, 1))

firmware_cmake = Path("firmware/components/storage/CMakeLists.txt")
text = firmware_cmake.read_text()
needle = '    "storage_package_export.c"\n'
if text.count(needle) != 1 or "storage_package_replace.c" in text:
    raise SystemExit("firmware package source insertion point changed")
firmware_cmake.write_text(text.replace(needle, needle + '    "storage_package_replace.c"\n', 1))

host_cmake = Path("tests/host/CMakeLists.txt")
text = host_cmake.read_text()
needle = '''# Register one isolated storage-object repository host test.
function(add_storage_object_repository_test target source mount_name)
'''
target = '''add_executable(
    storage_package_replace_tests
    test_storage_package_replace.c
    ${STORAGE_OBJECT_REPOSITORY_SOURCES}
    ../../firmware/components/macro_parser/macro_parser.c
    ../../firmware/components/macro_parser/macro_keymap_us.c
    ../../firmware/components/storage/storage_package.c
    ../../firmware/components/storage/storage_package_replace.c
    ../../firmware/components/storage/storage_set_tree.c
)
target_include_directories(
    storage_package_replace_tests
    PRIVATE ../../firmware/components/macro_model/include
            ../../firmware/components/macro_parser/include
            ../../firmware/components/storage/include
            ../../firmware/components/storage
)
target_compile_definitions(
    storage_package_replace_tests
    PRIVATE STORAGE_DATA_MOUNT="${CMAKE_CURRENT_BINARY_DIR}/storage-package-replace-data"
)
target_compile_options(storage_package_replace_tests PRIVATE ${STRICT_WARNINGS})
target_link_libraries(storage_package_replace_tests PRIVATE PkgConfig::CJSON test_support)
add_test(NAME storage_package_replace COMMAND storage_package_replace_tests)
set_tests_properties(storage_package_replace PROPERTIES LABELS "storage")

'''
if text.count(needle) != 1 or "storage_package_replace_tests" in text:
    raise SystemExit("host package replace target insertion point changed")
host_cmake.write_text(text.replace(needle, target + needle, 1))
